// Proves the hand-written Dart port of packages/tokens agrees with the JS
// original. test/fixtures/token_cases.json is GENERATED by
// `node packages/tokens/scripts/sync.js` from the JS code itself, so every
// value below is what the Expo app and the web platform compute.
//
// If this fails after a tokens change: fix the Dart port (lib/theme/*.dart),
// never the fixtures.

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:neuropal/theme/appearance.dart';
import 'package:neuropal/theme/classic_palette.dart';
import 'package:neuropal/theme/color_math.dart';
import 'package:neuropal/theme/pal.dart';
import 'package:neuropal/theme/signal_palette.dart';
import 'package:neuropal/theme/tokens.g.dart';

Map<String, Object?> _loadFixtures() {
  final file = File('test/fixtures/token_cases.json');
  return jsonDecode(file.readAsStringSync()) as Map<String, Object?>;
}

List<Map<String, Object?>> _cases(Map<String, Object?> fixtures, String key) =>
    (fixtures[key] as List).cast<Map<String, Object?>>();

/// Compares EVERY key the JS output carries (strings exactly, numbers by
/// value — JSON turns 1.0 into 1, which Dart's `==` treats as equal).
void _expectSameOutput(Map<String, Object?> actual, Map<String, Object?> expected) {
  for (final key in expected.keys) {
    expect(actual.containsKey(key), isTrue, reason: 'missing key "$key"');
    expect(actual[key], equals(expected[key]), reason: 'key "$key"');
  }
}

void main() {
  final fixtures = _loadFixtures();

  test('fixtures were generated from the same tokens version', () {
    expect(fixtures['tokensVersion'], kTokensVersion);
  });

  group('classic (resolveClassicPalette)', () {
    final cases = _cases(fixtures, 'classic');
    test('covers every theme × accent', () => expect(cases.length, 16));
    for (final c in cases) {
      final input = c['input'] as Map<String, Object?>;
      test('${input['theme']} × ${input['accent']}', () {
        final out = resolveClassicPalette(input).toJson();
        _expectSameOutput(out, c['output'] as Map<String, Object?>);
      });
    }
  });

  group('signal (resolveSignalPalette)', () {
    final cases = _cases(fixtures, 'signal');
    for (var i = 0; i < cases.length; i++) {
      final c = cases[i];
      final input = c['input'] as Map<String, Object?>;
      test('#$i acc=${input['acc']} base=${input['base']}', () {
        final out = resolveSignalPalette(input).toJson();
        _expectSameOutput(out, c['output'] as Map<String, Object?>);
      });
    }

    // sync.js builds most Signal inputs with hslToHex(h, 1, l) — rebuilding
    // them here checks the Dart hslToHex against the JS one.
    test('hslToHex reproduces the fixture accents', () {
      final presetCount = kSignalPresets.length;
      var i = 0;
      for (var h = 0; h < 360; h += 30) {
        for (final l in [0.4, 0.56, 0.72]) {
          final expected =
              (cases[presetCount + i]['input'] as Map<String, Object?>)['acc'];
          expect(hslToHex(h, 1, l), expected, reason: 'h=$h l=$l');
          i += 1;
        }
      }
    });
  });

  group('pal (palFaceInk / palVisor)', () {
    for (final c in _cases(fixtures, 'pal')) {
      final body = c['body'] as String;
      final acc = c['acc'] as String;
      test('body $body, accent $acc', () {
        expect(palFaceInk(body), c['faceInk']);
        expect(palVisor(body, acc), c['visor']);
      });
    }
  });

  group('appearance (normalizeAppearance)', () {
    // Every interpretAppearance fixture carries a JS-normalised appearance
    // ("next"); normalising it again in Dart must change nothing.
    final nexts = _cases(fixtures, 'interpretAppearance')
        .map((c) => c['next'])
        .whereType<Map<String, Object?>>()
        .toList();

    test('JS-normalised objects round-trip unchanged', () {
      expect(nexts, isNotEmpty);
      for (final next in nexts) {
        expect(normalizeAppearance(next).toJson(), equals(next));
      }
    });

    test('resolveAppearancePalette follows the skin', () {
      for (final next in nexts) {
        final skin = next['skin'];
        final palette = resolveAppearancePalette(next).toJson();
        final expected = skin == 'signal'
            ? resolveSignalPalette(next['signal']).toJson()
            : resolveClassicPalette(next['classic']).toJson();
        expect(palette, equals(expected));
      }
    });
  });

  // ---- M2 ------------------------------------------------------------------
  // The Ask-Pal interpreters and Home day rules arrive with the M2 screens
  // ("Make it yours", "Arrange Home"). Their fixtures stay in the JSON so the
  // contract is visible; they are skipped until the Dart port exists.
  const m2 = 'TODO(M2): port interpret.js / home.js#effectiveTiles';
  test('interpretAppearance fixtures', () {}, skip: m2);
  test('interpretHome fixtures', () {}, skip: m2);
  test('effectiveTiles fixtures', () {}, skip: m2);
}
